def seed_document_catalog(apps, schema_editor):
    """يزرع بنودَ المنصّة ومددَ الحفظ — **idempotent** ولا يمسّ صفّاً موجوداً.

    `get_or_create` بمفتاحه الطبيعيّ `(tax_system, code)`: تشغيلُ الهجرة مرّةً
    ثانية (أو نداءُ اختبارٍ لها بعد زرعها) لا يكتب صفّاً ولا يعيد كتابة صفٍّ
    صُحِّح لاحقاً.
    """
    PlatformDocumentItem = apps.get_model("accounting_office", "PlatformDocumentItem")
    DocumentRetentionRule = apps.get_model(
        "accounting_office", "DocumentRetentionRule",
    )
    for tax_system, items in SEED_ITEMS.items():
        for position, (code, name, cadence, service_codes, conditions) in enumerate(
            items, start=1,
        ):
            PlatformDocumentItem.objects.get_or_create(
                tax_system=tax_system,
                code=code,
                defaults={
                    "name": name,
                    "cadence": cadence,
                    "service_codes": list(service_codes),
                    "card_conditions": dict(conditions),
                    "sort_order": position,
                },
            )
    for tax_system, rows in SEED_RETENTION.items():
        for row in rows:
            DocumentRetentionRule.objects.get_or_create(
                tax_system=tax_system,
                code=row["code"],
                defaults={
                    "name": row["name"],
                    "years": row["years"],
                    "alt_years": row["alt_years"],
                    "basis": row["basis"],
                    "source_url": row["source_url"],
                },
            )


def unseed_document_catalog(apps, schema_editor):
    """عكسٌ يحذف **أكواد البذرة وحدها** — لا بنداً أضافه المكتب ولا مدةً أخرى."""
    PlatformDocumentItem = apps.get_model("accounting_office", "PlatformDocumentItem")
    DocumentRetentionRule = apps.get_model(
        "accounting_office", "DocumentRetentionRule",
    )
    for model, pairs in (
        (PlatformDocumentItem, _PLATFORM_CODES),
        (DocumentRetentionRule, _RETENTION_CODES),
    ):
        for tax_system, code in pairs:
            model.objects.filter(tax_system=tax_system, code=code).delete()


